<?php use App\Core\Csrf; use App\Core\View; $labels=['single'=>'单选题','multiple'=>'多选题','judge'=>'判断题','fill'=>'填空题'];$options=json_decode($question['options_json'],true)?:[];$correct=json_decode($question['correct_answers_json'],true)?:[];$answer=json_decode($question['answer_json']??'[]',true)?:[];$final=$question['is_correct']!==null;$fillWaiting=$question['question_type']==='fill'&&$question['answered_at']!==null&&!$final;$return='/student/study/'.$round['id'].'?n='.$position; ?>
<div class="page-head"><div><div class="eyebrow"><?= View::e(($question['section']??'理论题').' · '.($question['chapter']??'未分类')) ?></div><h1>第 <?= (int)$round['round_number'] ?> 轮顺序学习</h1><p>第 <?= (int)$position ?> / <?= (int)$round['total_count'] ?> 题 · <?= View::e($labels[$question['question_type']]??$question['question_type']) ?></p></div><a class="btn" href="/student">保存并退出</a></div>
<div class="progress-track"><span style="width:<?= round($round['completed_count']/max(1,$round['total_count'])*100,2) ?>%"></span></div>
<article class="card study-question-card">
<div class="toolbar spread"><div><span class="badge"><?= View::e($labels[$question['question_type']]??$question['question_type']) ?></span><?php if($question['source_order']):?><span class="muted">原题序号 <?= (int)$question['source_order'] ?></span><?php endif;?></div><div class="toolbar"><form method="post" action="/student/question/<?= (int)$question['source_question_id'] ?>/favorite"><?= Csrf::field() ?><input type="hidden" name="return_to" value="<?= View::e($return) ?>"><button class="btn btn-sm <?= !empty($question['favorite'])?'btn-primary':'' ?>"><?= !empty($question['favorite'])?'★ 已收藏':'☆ 收藏' ?></button></form><form method="post" action="/student/question/<?= (int)$question['source_question_id'] ?>/review-flag"><?= Csrf::field() ?><input type="hidden" name="return_to" value="<?= View::e($return) ?>"><button class="btn btn-sm <?= !empty($question['needs_review'])?'btn-warning':'' ?>"><?= !empty($question['needs_review'])?'△ 待复习':'○ 标记待复习' ?></button></form></div></div>
<h2><?= View::e($question['title']) ?></h2><div class="prompt study-prompt"><?= nl2br(View::e($question['prompt'])) ?></div>

<?php if(!$final&&!$fillWaiting):?><form method="post" action="/student/study/<?= $round['id'] ?>/question/<?= $question['id'] ?>/answer"><?= Csrf::field() ?><input type="hidden" name="position" value="<?= (int)$position ?>">
<?php if($question['question_type']==='fill'):?><div class="field top-gap"><label>你的答案</label><input name="answer_text" autocomplete="off" required autofocus></div><button class="btn btn-primary top-gap">查看标准答案</button>
<?php else:$input=($question['question_type']==='multiple'||count($correct)>1)?'checkbox':'radio';?><div class="options top-gap"><?php foreach($options as$letter=>$text):?><label class="option option-large"><input type="<?= $input ?>" name="answer[]" value="<?= View::e($letter) ?>"><strong><?= $question['question_type']==='judge'?View::e($text):View::e($letter).'.' ?></strong><?php if($question['question_type']!=='judge'):?><span><?= View::e($text) ?></span><?php endif;?></label><?php endforeach;?></div><button class="btn btn-primary top-gap">提交答案</button><?php endif;?></form><?php endif;?>

<?php if($fillWaiting):?><section class="answer-panel"><div class="result-title">请对照标准答案自评</div><p>你的答案：<strong><?= View::e($answer[0]??'') ?></strong></p><p>标准答案：<strong><?= View::e($correct?implode(' / ',$correct):'题库原文未提供标准答案') ?></strong></p><?php if($question['explanation']):?><div class="answer-reference"><?= nl2br(View::e($question['explanation'])) ?></div><?php endif;?><form class="toolbar top-gap" method="post" action="/student/study/<?= $round['id'] ?>/question/<?= $question['id'] ?>/answer"><?= Csrf::field() ?><input type="hidden" name="position" value="<?= (int)$position ?>"><button class="btn btn-success" name="self_result" value="correct">我答对了</button><button class="btn btn-warning" name="self_result" value="review">需要复习</button></form></section><?php endif;?>

<?php if($final):?><section class="answer-panel <?= $question['is_correct']?'answer-ok':'answer-bad' ?>"><div class="result-title"><?= $question['is_correct']?'✓ 回答正确':'✕ 回答错误' ?></div><?php if(!$question['is_correct']):?><p>这道题已保留在历史错题中，并加入复习队列。</p><?php endif;?><p>你的答案：<strong><?php if($question['question_type']==='judge')echo View::e(($answer[0]??'')==='T'?'对':'错');else echo View::e(implode('、',$answer));?></strong></p><p>正确答案：<strong><?php if($question['question_type']==='judge')echo View::e(($correct[0]??'')==='T'?'对':'错');else echo View::e($correct?implode(' / ',$correct):'题库原文未提供标准答案');?></strong></p><?php if($question['explanation']):?><div class="answer-reference"><?= nl2br(View::e($question['explanation'])) ?></div><?php else:?><div class="muted">题库未提供详细解析。</div><?php endif;?></section><?php endif;?>
</article>
<div class="sticky-actions"><div><?php if($position>1):?><a class="btn" href="/student/study/<?= $round['id'] ?>?n=<?= $position-1 ?>">← 上一题</a><?php endif;?></div><div class="toolbar"><?php if($round['status']==='completed'):?><a class="btn btn-primary" href="/student">本轮完成，查看统计</a><?php elseif($final&&$position<(int)$round['total_count']):?><a class="btn btn-primary" href="/student/study/<?= $round['id'] ?>?n=<?= $position+1 ?>">下一题 →</a><?php elseif($final):?><a class="btn btn-primary" href="/student/study/<?= $round['id'] ?>">完成本轮</a><?php else:?><span class="muted">完成当前题后进入下一题</span><?php endif;?></div></div>
